{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { readFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const directory = dirname(fileURLToPath(import.meta.url));
const database = new DatabaseSync(process.env.DB_PATH || join(directory, 'workboard.sqlite'));
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0 CHECK (completed IN (0, 1))
  )
`);

// Add the archive flag to databases created by earlier versions of Workboard.
const projectColumns = database.prepare('PRAGMA table_info(projects)').all();
if (!projectColumns.some((column) => column.name === 'archived')) {
  database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0 CHECK (archived IN (0, 1))');
}

const listProjects = database.prepare(`
  SELECT p.id, p.name, p.archived,
    COUNT(t.id) AS total_count,
    COALESCE(SUM(t.completed), 0) AS completed_count
  FROM projects p LEFT JOIN tasks t ON t.project_id = p.id
  WHERE p.archived = ? GROUP BY p.id ORDER BY p.id
`);
const findProject = database.prepare('SELECT id, name, archived FROM projects WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const setProjectArchived = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ?');
const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const findTask = database.prepare('SELECT id, title, completed FROM tasks WHERE id = ? AND project_id = ?');
const updateTaskCompletion = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

function sendJson(response, status, value) {
  response.writeHead(status, { 'Content-Type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(value));
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(project = null) {
  const template = readFileSync(join(directory, 'index.html'), 'utf8');
  const initialProject = project ? JSON.stringify(project).replace(/</g, '\\u003c') : 'null';
  return template.replace('<!-- PROJECT_DATA -->', `<script>window.initialProject = ${initialProject};</script>`)
    .replace('<!-- PROJECT_HEADING -->', project ? escapeHtml(project.name) : '');
}

async function readJson(request) {
  let body = '';
  for await (const chunk of request) {
    body += chunk;
    if (body.length > 16_384) throw new Error('Request body too large');
  }
  return JSON.parse(body);
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');

  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(response, 200, listProjects.all(url.searchParams.get('filter') === 'Archived' ? 1 : 0));
  }
  const archiveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/(archive|restore)$/);
  if (request.method === 'POST' && archiveMatch) {
    const projectId = Number(archiveMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    setProjectArchived.run(archiveMatch[2] === 'archive' ? 1 : 0, projectId);
    return sendJson(response, 200, findProject.get(projectId));
  }
  const renameMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/rename$/);
  if (request.method === 'POST' && renameMatch) {
    const projectId = Number(renameMatch[1]);
    const project = findProject.get(projectId);
    if (!project) return sendJson(response, 404, { error: 'Project not found' });
    if (project.archived) return sendJson(response, 400, { error: 'Archived projects cannot be renamed' });
    try {
      const payload = await readJson(request);
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      renameProject.run(name, projectId);
      return sendJson(response, 200, findProject.get(projectId));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    try {
      const payload = await readJson(request);
      const name = typeof payload.name === 'string' ? payload.name.trim() : '';
      if (!name) return sendJson(response, 400, { error: 'Project name is required' });
      const result = createProject.run(name);
      return sendJson(response, 201, findProject.get(result.lastInsertRowid));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!findProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    if (request.method === 'GET') return sendJson(response, 200, listTasks.all(projectId));
    if (request.method === 'POST') {
      try {
        if (findProject.get(projectId).archived) return sendJson(response, 400, { error: 'Archived projects cannot have tasks' });
        const payload = await readJson(request);
        const title = typeof payload.title === 'string' ? payload.title.trim() : '';
        if (!title) return sendJson(response, 400, { error: 'Task title is required' });
        const result = createTask.run(projectId, title);
        return sendJson(response, 201, findTask.get(result.lastInsertRowid, projectId));
      } catch {
        return sendJson(response, 400, { error: 'Invalid request' });
      }
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  if (request.method === 'PATCH' && taskMatch) {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    if (!findProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    try {
      if (findProject.get(projectId).archived) return sendJson(response, 400, { error: 'Archived project tasks cannot be changed' });
      const payload = await readJson(request);
      if (typeof payload.completed !== 'boolean') return sendJson(response, 400, { error: 'Completion must be a boolean' });
      const result = updateTaskCompletion.run(payload.completed ? 1 : 0, taskId, projectId);
      if (!Number(result.changes)) return sendJson(response, 404, { error: 'Task not found' });
      return sendJson(response, 200, findTask.get(taskId, projectId));
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
  }
  if (request.method === 'GET' && url.pathname === '/') {
    response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return response.end(page());
  }
  const projectMatch = url.pathname.match(/^\/projects\/(\d+)$/);
  if (request.method === 'GET' && projectMatch) {
    const project = findProject.get(Number(projectMatch[1]));
    if (!project) {
      response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
      return response.end('Project not found');
    }
    response.writeHead(200, { 'Content-Type': 'text/html; charset=utf-8' });
    return response.end(page(project));
  }
  response.writeHead(404, { 'Content-Type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Workboard</title>
  <style>
    :root { color-scheme: light; font-family: system-ui, sans-serif; color: #202b3c; background: #f4f6f9; }
    body { margin: 0; }
    main { max-width: 760px; margin: 64px auto; padding: 0 24px; }
    h1 { margin: 0 0 28px; font-size: 2rem; }
    form, .project-row, .detail, .task-row { background: white; border: 1px solid #dce2ea; border-radius: 10px; padding: 20px; }
    form { display: flex; align-items: end; gap: 12px; flex-wrap: wrap; }
    label { display: grid; gap: 7px; flex: 1; min-width: 200px; font-weight: 600; }
    input { box-sizing: border-box; width: 100%; padding: 10px 12px; border: 1px solid #aab5c4; border-radius: 6px; font: inherit; }
    button { padding: 10px 15px; border: 0; border-radius: 6px; background: #245fce; color: white; font: inherit; font-weight: 600; cursor: pointer; }
    button:hover { background: #194da9; }
    .project-list { display: grid; gap: 10px; margin-top: 22px; }
    .project-row { display: flex; align-items: center; justify-content: space-between; gap: 16px; }
    .project-actions { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
    .project-summary { color: #657083; white-space: nowrap; }
    .project-name { overflow-wrap: anywhere; }
    .alert { margin: 12px 0 0; color: #a32828; }
    .detail p { margin: 0 0 20px; }
    .task-controls { margin-top: 20px; }
    .task-controls label { flex: 1; }
    .task-row { display: flex; align-items: center; gap: 12px; }
    .task-row input { width: auto; }
    .task-title { overflow-wrap: anywhere; }
    .task-row.completed .task-title { color: #657083; text-decoration: line-through; }
  </style>
</head>
<body>
  <main id="app">
    <h1>Workboard</h1>
    <form id="create-form">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Create project</button>
    </form>
    <p id="alert" class="alert" role="alert" hidden></p>
    <label for="project-filter" style="margin-top: 20px">Project filter</label>
    <select id="project-filter"><option>Active</option><option>Archived</option></select>
    <section id="project-list" class="project-list" aria-label="Projects"></section>
  </main>
  <main id="project-detail" hidden>
    <button id="back-button" type="button">Projects</button>
    <h1 id="project-heading"><!-- PROJECT_HEADING --></h1>
    <p id="archived-notice" hidden>Archived project</p>
    <form id="rename-form" class="task-controls">
      <label for="new-project-name">New project name</label>
      <input id="new-project-name" name="name" type="text" autocomplete="off">
      <button type="submit">Rename project</button>
    </form>
    <p id="rename-alert" class="alert" role="alert" hidden></p>
    <form id="task-form" class="task-controls">
      <label for="task-title-input">Task title</label>
      <input id="task-title-input" name="title" type="text" autocomplete="off">
      <button type="submit">Create task</button>
    </form>
    <p id="task-alert" class="alert" role="alert" hidden></p>
    <label for="task-filter" style="margin-top: 20px">Task filter</label>
    <select id="task-filter">
      <option>All</option><option>Open</option><option>Completed</option>
    </select>
    <section id="task-list" class="project-list" aria-label="Tasks"></section>
  </main>
  <!-- PROJECT_DATA -->
  <script>
    const app = document.querySelector('#app');
    const detail = document.querySelector('#project-detail');
    if (window.initialProject) {
      app.hidden = true;
      detail.hidden = false;
      const projectId = window.initialProject.id;
      const list = document.querySelector('#task-list');
      const alert = document.querySelector('#task-alert');
      const input = document.querySelector('#task-title-input');
      const filter = document.querySelector('#task-filter');
      const archived = Boolean(window.initialProject.archived);
      document.querySelector('#archived-notice').hidden = !archived;
      const renameInput = document.querySelector('#new-project-name');
      const renameButton = document.querySelector('#rename-form button');
      const renameAlert = document.querySelector('#rename-alert');
      renameInput.disabled = archived;
      renameButton.disabled = archived;
      document.querySelector('#task-title-input').disabled = archived;
      document.querySelector('#task-form button').disabled = archived;
      let tasks = [];
      const escapeText = (value) => {
        const element = document.createElement('span');
        element.textContent = value;
        return element.innerHTML;
      };
      const renderTasks = () => {
        const visibleTasks = tasks.filter((task) => filter.value === 'All'
          || (filter.value === 'Open' && !task.completed)
          || (filter.value === 'Completed' && task.completed));
        list.innerHTML = visibleTasks.map((task) => `
          <div class="task-row${task.completed ? ' completed' : ''}" data-testid="task-row">
            <input type="checkbox" data-task-id="${task.id}" aria-label="Complete ${escapeText(task.title)}"${task.completed ? ' checked' : ''}${archived ? ' disabled' : ''}>
            <span class="task-title">${escapeText(task.title)}</span>
          </div>`).join('');
      };
      const loadTasks = async () => {
        const response = await fetch(`/api/projects/${projectId}/tasks`);
        if (response.ok) {
          tasks = await response.json();
          renderTasks();
        }
      };
      loadTasks();
      filter.addEventListener('change', renderTasks);
      document.querySelector('#rename-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = renameInput.value.trim();
        if (!name) {
          renameAlert.textContent = 'Project name is required';
          renameAlert.hidden = false;
          renameInput.focus();
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/rename`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (!response.ok) {
          const result = await response.json();
          renameAlert.textContent = result.error || 'Unable to rename project';
          renameAlert.hidden = false;
          return;
        }
        const project = await response.json();
        document.querySelector('#project-heading').textContent = project.name;
        renameInput.value = '';
        renameAlert.hidden = true;
      });
      document.querySelector('#task-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const title = input.value.trim();
        if (!title) {
          alert.textContent = 'Task title is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/tasks`, {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ title }),
        });
        if (!response.ok) {
          const result = await response.json();
          alert.textContent = result.error || 'Unable to create task';
          alert.hidden = false;
          return;
        }
        input.value = '';
        alert.hidden = true;
        await loadTasks();
      });
      list.addEventListener('change', async (event) => {
        const checkbox = event.target.closest('input[type="checkbox"][data-task-id]');
        if (!checkbox) return;
        const response = await fetch(`/api/projects/${projectId}/tasks/${checkbox.dataset.taskId}`, {
          method: 'PATCH', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        if (response.ok) {
          const updated = await response.json();
          tasks = tasks.map((task) => task.id === updated.id ? updated : task);
          renderTasks();
        } else {
          await loadTasks();
        }
      });
    } else {
      const list = document.querySelector('#project-list');
      const alert = document.querySelector('#alert');
      const input = document.querySelector('#project-name');
      const filter = document.querySelector('#project-filter');
      const escapeText = (value) => {
        const element = document.createElement('span');
        element.textContent = value;
        return element.innerHTML;
      };
      const render = (projects) => {
        list.innerHTML = projects.map((project) => `
          <div class="project-row" data-testid="project-row">
            <span class="project-name">${escapeText(project.name)}</span>
            <span class="project-summary" data-testid="project-summary">${project.completed_count}/${project.total_count} completed</span>
            <span class="project-actions">
              <button type="button" data-project-id="${project.id}" data-action="open">Open project</button>
              <button type="button" data-project-id="${project.id}" data-action="${project.archived ? 'restore' : 'archive'}">${project.archived ? 'Restore project' : 'Archive project'}</button>
            </span>
          </div>`).join('');
      };
      const loadProjects = () => fetch(`/api/projects?filter=${filter.value}`).then((response) => response.json()).then(render);
      loadProjects();
      filter.addEventListener('change', loadProjects);
      document.querySelector('#create-form').addEventListener('submit', async (event) => {
        event.preventDefault();
        const name = input.value.trim();
        if (!name) {
          alert.textContent = 'Project name is required';
          alert.hidden = false;
          input.focus();
          return;
        }
        const response = await fetch('/api/projects', {
          method: 'POST', headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ name }),
        });
        if (!response.ok) {
          const result = await response.json();
          alert.textContent = result.error || 'Unable to create project';
          alert.hidden = false;
          return;
        }
        const project = await response.json();
        input.value = '';
        alert.hidden = true;
        await loadProjects();
      });
      list.addEventListener('click', async (event) => {
        const button = event.target.closest('button[data-project-id]');
        if (!button) return;
        const { projectId, action } = button.dataset;
        if (action === 'open') {
          window.location.href = `/projects/${projectId}`;
          return;
        }
        const response = await fetch(`/api/projects/${projectId}/${action}`, { method: 'POST' });
        if (response.ok) await loadProjects();
      });
    }
    document.querySelector('#back-button').addEventListener('click', () => {
      window.location.href = '/';
    });
  </script>
</body>
</html>
